    aeo: [{"pergunta":"O que aconteceu?","resposta":"Acompanhe a apuração para presidente e governador em seu Estado e município com o mapa interativo da BBC News Brasil"},{"pergunta":"Qual é o ponto principal?","resposta":"Os principais veículos da imprensa internacional estão dando grande destaque à vitória eleitoral de Luiz Inácio Lula da Silva (PT) , que terá o seu quarto mandato presidencial após derrotar Flávio Bolsonaro (PL)."},{"pergunta":"Quais são os dados mais importantes?","resposta":"O site do jornal americano The New York Times noticia a vitória de Lula como manchete principal: &quot;Lula é reeleito, enquanto Bolsonaro rejeita resultado&quot;."},{"pergunta":"Qual é o contexto?","resposta":"De acordo com o jornal, Lula &quot;conteve um movimento de direita&quot; liderado por Flávio Bolsonaro . Problemas no transporte público e &quot;condições climáticas&quot; prejudicaram a votação, acrescenta."},{"pergunta":"Quais são os próximos desdobramentos?","resposta":"Em outra reportagem, o jornal americano chama Lula de &quot;estadista mais importante da América Latina&quot;."}],
